pub fn line_prefix_authority_note() -> String {
    thread_local! {
        static CACHED: String = {
            "Placement is decided by the PHYSICAL LINE PREFIX — the raw text between the last line feed and the annotation — and never by which lexical category the preceding lexeme belonged to.\n\nThe category guess is wrong, and a real grammar disproves it. Deciding `leading` by `no semantic token seen on this line yet` assumes line boundaries live in trivia; the Python model's own token lexemes include `):\\n    `, which ENDS on a fresh line carrying only indentation, and `\\n    if `, which ends on a fresh line carrying semantic text. An annotation after the first is leading and after the second is trailing, yet a category rule classifies both as trailing because in both cases the last thing consumed was a semantic token. Any grammar whose tokens may span lines breaks the same way.\n\nSo the state is `line prefix is indent only`, advanced by the RAW TEXT of every consumed lexeme regardless of category. One fold expresses the whole rule: a line feed resets the prefix to empty (vacuously indent-only), and every character after it must be indentation for the prefix to stay so. A lexeme with no line feed therefore preserves the previous state only while it is itself indentation, and a lexeme containing one is judged entirely by what follows its LAST line feed — both cases the fold produces without a special arm. An empty lexeme preserves the state.\n\nA lexer that walks lexemes threads this forward; a lexer with random access to the source feeds it the raw slice it consumed between steps. Both consume THIS function, because two spellings of one placement rule would let the realizations disagree about the same source.".to_string()
        };
    }
    CACHED.with(|c: &String| c.clone())
}

pub fn code_point_is_line_feed(cp: i64) -> bool {
    (cp.clone() == 10)
}

pub fn code_point_is_indent(cp: i64) -> bool {
    ((cp.clone() == 32) || (cp.clone() == 9))
}

