pub fn annotation_subject_pick_note() -> String {
    thread_local! {
        static CACHED: String = {
            "Resolves one capture against the subject roster in a single pass, answering both questions the attachment rule asks: is the capture INSIDE some subject (body grain, refused), and what is the nearest subject STARTING AFTER it (its leading subject). Containment is checked before proximity because the two overlap — prose inside a function body always has some later declaration after it, and picking that one would silently reattach body commentary to the next unrelated declaration. That is the specific misattachment BodyGrainNotModeled exists to prevent, and checking proximity first would produce a plausible wrong answer rather than a refusal.\n\nThe roster is scanned rather than indexed, so resolution is captures times subjects. That is a join without a sorted index, not a copied accumulator, and it is bounded by one source's declarations. DISSOLVE-ON: a span-ordered subject index exists on the parse artifact; then the nearest-following pick becomes a lookup and this fold reads it.".to_string()
        };
    }
    CACHED.with(|c: &String| c.clone())
}

#[derive(Debug, Clone, PartialEq, serde::Serialize, serde::Deserialize)]
pub struct AnnotationSubjectPick {
    pub contained: bool,
    pub following: Option<Rc<AnnotationSubject>>,
}

pub fn annotation_subject_pick(
    subjects: Rc<Vec<Rc<AnnotationSubject>>>,
    origin: Rc<SourceSpan>,
) -> Rc<AnnotationSubjectPick> {
    subjects.clone().iter().cloned().fold(
        Rc::new(AnnotationSubjectPick {
            contained: false,
            following: None,
        }),
        |acc: Rc<AnnotationSubjectPick>, subject: Rc<AnnotationSubject>| {
            if ((origin.start.clone() >= subject.span.clone().start.clone())
                && (origin.end.clone() <= subject.span.clone().end.clone()))
            {
                Rc::new(AnnotationSubjectPick {
                    contained: true,
                    following: acc.following.clone(),
                })
            } else {
                if (subject.span.clone().start.clone() < origin.end.clone()) {
                    acc.clone()
                } else {
                    match acc.following.clone() {
                        None => Rc::new(AnnotationSubjectPick {
                            contained: acc.contained.clone(),
                            following: Some(subject.clone()),
                        }),
                        Some(best) => {
                            if (subject.span.clone().start.clone()
                                < best.span.clone().start.clone())
                            {
                                Rc::new(AnnotationSubjectPick {
                                    contained: acc.contained.clone(),
                                    following: Some(subject.clone()),
                                })
                            } else {
                                acc.clone()
                            }
                        }
                    }
                }
            }
        },
    )
}

pub fn annotation_block_grouping_note() -> String {
    thread_local! {
        static CACHED: String = {
            "A BLANK LINE SPLITS A BLOCK. Two facts decide grouping — same following subject, and physical adjacency — and both are required.\n\nAn earlier revision used same-subject alone and claimed those captures were `by construction consecutive`. They are not. Two comment lines directly above a declaration and two comment BLOCKS separated by a blank line above the SAME declaration both resolve to that one subject, so same-subject alone merged them into a single row joined by a single newline and the blank line ceased to exist. That is not a formatting nicety: the authored structure is gone, and once a renderer exists it would render one block where the author wrote two, permanently.\n\nAdjacency cannot be recovered here — the fold sees spans, not source, and the whitespace between two captures was consumed by the lexer — so it is OBSERVED at capture, exactly like placement and for exactly the same reason. `preceded_by_blank_line` is that observation, and this fold reads it rather than re-deriving it.\n\nThe merged row's text carries its own line breaks and its origin spans first capture start to last capture end, so a block is addressable as one authored unit. `pending` holds the block still being extended; it is flushed when a capture resolves to a different subject, when a capture opens a new block after a blank line, and once more at the end.".to_string()
        };
    }
    CACHED.with(|c: &String| c.clone())
}

